#include "dfre/mission_client_startup.hpp"
#include <array>
#include <iostream>
#include <sstream>
#include <unordered_map>
using namespace dfre;
int main(){try{std::string line;while(std::getline(std::cin,line)){if(line.empty())continue;std::istringstream in(line);std::uint32_t h[11];for(auto& x:h){std::uint64_t n;if(!(in>>n))throw MissionClientStartupError("Short startup fixture");x=std::uint32_t(n);}std::unordered_map<std::uint32_t,std::uint8_t> memory;std::vector<std::array<std::uint32_t,3>> initial;const auto put=[&](auto at,unsigned width,auto n){for(unsigned i=0;i<width;++i)memory[at+i]=std::uint8_t(n>>(8*i));};const auto get=[&](auto at,unsigned width){std::uint32_t n=0;for(unsigned i=0;i<width;++i){const auto p=memory.find(at+i);if(p!=memory.end())n|=std::uint32_t(p->second)<<(8*i);}return n;};for(unsigned i=0;i<h[10];++i){std::array<std::uint32_t,3> row;if(!(in>>row[0]>>row[1]>>row[2]))throw MissionClientStartupError("Short startup memory");put(row[0],row[1],row[2]);initial.push_back(row);}unsigned seen=0;std::ostringstream trace;MissionClientStartupBindings b;
b.read=[&](auto at,auto width){if(at==h[4]&&seen++==h[5])put(at,width,h[6]);const auto n=get(at,width);trace<<'R'<<at<<','<<width<<','<<n<<';';return n;};b.write=[&](auto at,auto width,auto n){trace<<'W'<<at<<','<<width<<','<<n<<';';put(at,width,n);};
b.before_call=[&](auto site,const auto& args){trace<<'C'<<site;for(auto n:args)trace<<','<<n;trace<<';';if(site==h[7])put(h[8],4,h[9]);};
b.call=[&](auto site,const auto& args)->std::uint32_t{if(site==0x49a620){for(auto i=memory.begin();i!=memory.end();){if(std::uint32_t(i->first-args[0])<args[2])i=memory.erase(i);else ++i;}return args[0];}if(site==0x404cf0)return 0x1300100;if(site==0x454df0)return 0x11223344;if(site==0x454bb0||site==0x4568e0)return 0;throw MissionClientStartupError("Unexpected startup service");};
switch(h[0]){case 0:mission_client_startup(b);break;case 1:mission_client_assign_team(b,h[1],h[2]);break;case 2:mission_client_setup_local(b,h[1],h[2],h[3]);break;case 3:mission_client_register_input(b,h[1]);break;case 4:mission_client_register_callback(b,h[1],h[2]);break;case 5:mission_client_reset_banned(b);break;default:throw MissionClientStartupError("Unknown startup operation");}for(const auto& row:initial)trace<<'V'<<row[0]<<','<<row[1]<<','<<get(row[0],row[1])<<';';std::cout<<trace.str()<<'\n';}}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
